func (r *AgentRunResolver) Definition(ctx context.Context, obj *agent.AgentRun) (*agentdefinition.Definition, error) {
	if obj.AgentDefinitionID.IsNil() {
		return nil, nil
	}

	if !loaders.Available(ctx) {
		return nil, nil
	}

	definition, err := loaders.AgentDefinitionByID(ctx, obj.AgentDefinitionID.String())
	if err != nil {
		// A run of a retired built-in agent names a definition that is gone;
		// the run is still worth showing.
		if errortypes.IsNotFoundError(err) {
			return nil, nil
		}

		return nil, err
	}

	return definition, nil
}

func (r *AgentRunResolver) HandedBy(ctx context.Context, obj *agent.AgentRun) (*agentdefinition.Definition, error) {
	if obj.ParentOwnerKind != agent.RunOwnerAssistantTurn ||
		obj.SubjectType != agent.SubjectAssistantThread || obj.SubjectID.IsNil() {
		return nil, nil
	}

	if !loaders.Available(ctx) {
		return nil, nil
	}

	thread, err := loaders.ThreadAgentByID(ctx, obj.SubjectID.String())
	if err != nil {
		if errortypes.IsNotFoundError(err) {
			return nil, nil
		}

		return nil, err
	}
	if thread.AgentDefinitionID.IsNil() || thread.AgentDefinitionID == obj.AgentDefinitionID {
		return nil, nil
	}

	definition, err := loaders.AgentDefinitionByID(ctx, thread.AgentDefinitionID.String())
	if err != nil {
		if errortypes.IsNotFoundError(err) {
			return nil, nil
		}

		return nil, err
	}

	return definition, nil
}

