func (r *QueryResolver) PendingDecisions(ctx context.Context, input gqlmodel.PendingDecisionsInput) (*gqlmodel.PendingDecisionConnection, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceAgentProposal, permission.OpRead)
	if err != nil {
		return nil, err
	}

	usable, err := r.PermissionEngine.AgentsUsable(
		ctx,
		actorutil.FromAuthContext(authCtx),
		permission.OpRead,
	)
	if err != nil {
		return nil, err
	}

	req := agentports.ListPendingDecisionsRequest{
		TenantInfo:        base.TenantInfo(authCtx),
		IncludeTotalCount: base.ConnectionTotalRequested(ctx),
		Usable:            usable,
	}
	if input.First != nil {
		req.First = *input.First
	}
	if input.After != nil {
		req.After = *input.After
	}
	if input.ToolName != nil {
		req.ToolName = *input.ToolName
	}
	if input.AgentDefinitionID != nil && *input.AgentDefinitionID != "" {
		definitionID, parseErr := pulid.MustParse(*input.AgentDefinitionID)
		if parseErr != nil {
			return nil, parseErr
		}
		req.AgentDefinitionID = definitionID
	}

	page, err := r.AgentDecisionQueueService.ListPending(ctx, req)
	if err != nil {
		return nil, err
	}

	edges := make([]*gqlmodel.PendingDecisionEdge, 0, len(page.Items))
	for i := range page.Items {
		item := page.Items[i]
		var node gqlmodel.PendingDecision
		switch {
		case item.Proposal != nil:
			node = item.Proposal
		case item.Plan != nil:
			node = item.Plan
		default:
			continue
		}
		edges = append(edges, &gqlmodel.PendingDecisionEdge{Node: node, Cursor: item.Cursor})
	}

	pageInfo := &gqlmodel.PageInfo{HasNextPage: page.HasNextPage}
	if len(edges) > 0 {
		last := edges[len(edges)-1].Cursor
		pageInfo.EndCursor = &last
	}

	return &gqlmodel.PendingDecisionConnection{
		Edges:           edges,
		PageInfo:        pageInfo,
		TotalCount:      page.TotalCount,
		TotalCountExact: page.TotalCountExact,
	}, nil
}

